mapper.select:
SELECT s_c.student_id studentId, c.class_name className FROM bd_student_class s_c LEFT JOIN bd_class c ON s_c.class_id = c.id WHERE s_c.is_delete = 0 AND s_c.student_id IN
#{id}
AND s_c.mec_id = #{mecId} AND s_c.campus_id = #{campusId} ORDER BY s_c.student_id

SELECT count( id ) total_stu, class_id FROM bd_student_class WHERE class_id IN
#{id}
GROUP BY class_id

SELECT sc.id, sc.mec_id, sc.campus_id, sc.student_id, sc.class_id, sc.have_time, sc.is_delete, sc.create_time, sc.create_by, sc.update_time, sc.update_by FROM bd_student_class sc LEFT JOIN bd_student stu on sc.student_id = stu.id WHERE sc.class_id = #{classId}
stu.student_name LIKE CONCAT('%', #{studentName}, '%')
AND sc.is_delete = 0
